import {BypassDialog} from '@github-ui/bypass-actors/BypassDialog'
import {verifiedFetch} from '@github-ui/verified-fetch'
import type {BypassActor} from '@github-ui/bypass-actors/types'
import {Button} from '@primer/react'
import {useState} from 'react'

export interface SecretScanningBypassersDialogProps {
  baseAvatarUrl: string
  enabledBypassActors: BypassActor[]
  addBypasserPath: string
  initialSuggestions: BypassActor[]
  suggestionsUrl: string
  ownerId: number
  ownerScope: string
}

const bypasserType = (type: string) => {
  switch (type) {
    case 'Team':
      return 'TEAM'
    case 'RepositoryRole':
      return 'ROLE'
    case 'OrganizationAdmin':
      return 'ORG_ADMIN'
    case 'Integration':
      return 'INTEGRATION'
    case 'EnterpriseRole':
      return 'ENTERPRISE_ROLE'
    case 'BusinessTeam':
      return 'BUSINESS_TEAM'
    default:
      return 'UNKNOWN'
  }
}

export function SecretScanningBypassersDialog({
  baseAvatarUrl,
  enabledBypassActors,
  addBypasserPath,
  initialSuggestions,
  suggestionsUrl,
  ownerId,
  ownerScope,
}: SecretScanningBypassersDialogProps) {
  const [showDialog, setShowDialog] = useState(false)

  const addBypassActor = async (actorId: BypassActor['actorId'], actorType: BypassActor['actorType']) => {
    const formData = new FormData()
    formData.set('owner_id', ownerId.toString())
    formData.set('owner_scope', ownerScope)
    formData.set('reviewer_id', actorId?.toString() || '')
    formData.set('reviewer_type', bypasserType(actorType))

    const result = await verifiedFetch(addBypasserPath, {
      method: 'post',
      body: formData,
    })

    window.location.reload()
    return result
  }

  const onClose = (): void => {
    setShowDialog(false)
  }

  return (
    <>
      <Button onClick={() => setShowDialog(true)}>Add role or team</Button>
      {showDialog && (
        <BypassDialog
          baseAvatarUrl={baseAvatarUrl}
          enabledBypassActors={enabledBypassActors}
          initialSuggestions={initialSuggestions}
          onClose={onClose}
          addBypassActor={addBypassActor}
          suggestionsUrl={suggestionsUrl}
          addReviewerSubtitle={'Choose which roles and teams can bypass this ruleset'}
        />
      )}
    </>
  )
}
